#!/usr/bin/env python3
"""
R03 run22 exact checker: Schur/additive-energy selected-plane correction.

This checker is an exact-arithmetic finite certificate for the new n=11 metric move.

It verifies:
  * projective support-3 (+,+,-) and support-4 balanced null lines;
  * distinct 2-planes generated by support3/support3 and support3/support4 pairs;
  * a rigorous collision-free matrix-incidence lower bound for each selected plane,
    using exact Boolean cube intersections and the same row-bad union bound as R03-C254;
  * combinatorial caps on how many support3 and support4 lines can lie in one
    collision-free modular nullspace;
  * the pointwise selected-plane majorant for every modular nullity d<=5;
  * the exact improved collision-subtracted bound r(11).

No floating point is used for any certificate decision.
"""
from itertools import combinations
from fractions import Fraction
from math import comb

def fall(a,m):
    if a < m: return 0
    z=1
    for j in range(m): z*=a-j
    return z

def canon_line(v,p):
    v=tuple(x%p for x in v)
    for x in v:
        if x:
            inv=pow(x,-1,p)
            return tuple((y*inv)%p for y in v)
    raise ValueError

def rref2(a,b,p):
    A=[list(a),list(b)]
    m=len(a); r=0
    for c in range(m):
        piv=None
        for i in range(r,2):
            if A[i][c]%p:
                piv=i; break
        if piv is None: continue
        A[r],A[piv]=A[piv],A[r]
        inv=pow(A[r][c]%p,-1,p)
        A[r]=[(z*inv)%p for z in A[r]]
        for i in range(2):
            if i!=r and A[i][c]%p:
                f=A[i][c]%p
                A[i]=[(A[i][j]-f*A[r][j])%p for j in range(m)]
        r+=1
        if r==2: break
    return tuple(tuple(row) for row in A[:r])

def line_mask(v,p,m):
    mask=0
    for bits in range(1<<m):
        s=0
        for i,a in enumerate(v):
            if (bits>>i)&1: s+=a
        if s%p==0: mask |= 1<<bits
    return mask

def support3_lines(m,p):
    lines={}
    for S in combinations(range(m),3):
        for target in S:
            v=[0]*m
            for i in S: v[i]=1
            v[target]=-1
            lines[canon_line(v,p)]=None
    out=list(lines)
    assert len(out)==3*comb(m,3)
    return out

def support4_lines(m,p):
    lines={}
    for S in combinations(range(m),4):
        seen=set()
        for plus_t in combinations(S,2):
            plus=set(plus_t); v=[0]*m
            for i in S: v[i]=1 if i in plus else -1
            seen.add(canon_line(v,p))
        assert len(seen)==3
        for v in seen: lines[v]=None
    out=list(lines)
    assert len(out)==3*comb(m,4)
    return out

def bad_masks(m):
    out=[]
    for i in range(m):
        mask=0
        for bits in range(1<<m):
            if ((bits>>i)&1)==0: mask |= 1<<bits
        out.append(mask)
    for i in range(m):
        for j in range(i+1,m):
            mask=0
            for bits in range(1<<m):
                if ((bits>>i)&1)==((bits>>j)&1): mask |= 1<<bits
            out.append(mask)
    return out

def selected_plane_lower(m,p,kind):
    L3=support3_lines(m,p)
    L4=support4_lines(m,p)
    all_lines=set(L3+L4)
    masks={v:line_mask(v,p,m) for v in all_lines}
    Vmask={}
    if kind=="33":
        pairs=combinations(L3,2)
    elif kind=="34":
        pairs=((a,b) for a in L3 for b in L4)
    else:
        raise ValueError
    pair_mult={}
    for a,b in pairs:
        V=rref2(a,b,p)
        assert len(V)==2
        pair_mult[V]=pair_mult.get(V,0)+1
        if V not in Vmask:
            Vmask[V]=masks[a]&masks[b]
    bm=bad_masks(m)
    total_lb=0
    hdist={}
    positive=0
    for V,mask in Vmask.items():
        h=mask.bit_count()
        hdist[h]=hdist.get(h,0)+1
        total=fall(h-1,m)  # ordered, nonzero, pairwise-distinct columns
        bad=0
        for B in bm:
            t=(mask&B).bit_count()-1
            bad += fall(t,m)
        g=max(0,total-bad)
        if g:
            positive+=1
            total_lb+=g
    mdist={}
    for q in pair_mult.values(): mdist[q]=mdist.get(q,0)+1
    return len(L3),len(L4),len(Vmask),hdist,mdist,positive,total_lb

def qb(n,k,p):
    if k<0 or k>n:return 0
    if k==0:return 1
    num=den=1
    for i in range(k):
        num*=p**(n-i)-1
        den*=p**(k-i)-1
    assert num%den==0
    return num//den

# Standard q-binomial / projective inclusion-exclusion identity:
# 1_{d>=1} = sum_{k=1}^d (-1)^(k+1) p^(k choose 2) [d k]_p.
for p in (7,11):
    for d in range(0,9):
        s=sum(((-1)**(k+1))*p**(k*(k-1)//2)*qb(d,k,p)
              for k in range(1,d+1))
        assert s==(1 if d>=1 else 0)
print("q-binomial projective inclusion-exclusion d<=8 p=7,11 PASS")

# Main finite case: n=11, m=10, p=11.  R03-C256 gives d_p(A)<=5.
m=10; p=11; D=5
L3,L4,V33,h33,mult33,pos33,J33=selected_plane_lower(m,p,"33")
_,_,V34,h34,mult34,pos34,J34=selected_plane_lower(m,p,"34")
print("m=10 p=11 support3_lines",L3,"support4_lines",L4)
print("J33 unique_planes",V33,"positive_planes",pos33,
      "h_distribution",sorted(h33.items()),
      "pair_multiplicity",sorted(mult33.items()),
      "lower_incidence",J33)
print("J34 unique_planes",V34,"positive_planes",pos34,
      "h_distribution",sorted(h34.items()),
      "pair_multiplicity",sorted(mult34.items()),
      "lower_incidence",J34)

assert J33==152456868879257460494592000
assert J34==453567196534624641874944000

# Universal sparse-line caps in a collision-free nullspace.
# Support-3: for each target c_k, the pairs c_i+c_j=c_k form a matching on
# the other m-1 parity-check columns.
t3max=m*((m-1)//2)
assert t3max==40

# Support-4 balanced lines: group the C(m,2) unordered pairs by their pair sum.
# Each sum class is a matching, hence has size <=floor(m/2).  Convexity puts
# as many pair-edges as possible into full classes.
pair_edges=comb(m,2)
cap=m//2
q,r=divmod(pair_edges,cap)
t4max=q*comb(cap,2)+comb(r,2)
assert t4max==90
print("universal_line_caps t3max",t3max,"t4max",t4max)

# Selected plane caps:
# J33(d) <= min([d 2]_p, C(t3max,2))
# J34(d) <= min([d 2]_p, t3max*t4max)
# The chosen coefficients are the exact LP vertex where d=3 and d=4 bind.
b=Fraction(280621,375060)
e=Fraction(91619,375060)
assert b+e==Fraction(132,133)
print("coeff_b33",b,"coeff_b34",e)

for d in range(0,D+1):
    z1=qb(d,1,p)
    if d<2:
        j33=j34=0
    else:
        z2=qb(d,2,p)
        j33=min(z2,comb(t3max,2))
        j34=min(z2,t3max*t4max)
    lhs=Fraction(z1)-b*j33-e*j34
    rhs=1 if d>=1 else 0
    print("pointwise d",d,"Z1",z1,"J33cap",j33,"J34cap",j34,
          "majorant",lhs,"target",rhs)
    assert lhs>=rhs

# Retained exact first projective incidence from run17.
M1=325043331888785398807391827200
scale=Fraction(2**11,2**100)
new=scale*(Fraction(M1)-b*J33-e*J34)
expected=Fraction(1133058166724579425165689967575,
                  2159141513831727706025230336)
assert new==expected
prev=Fraction(4089568153828729532838706676925,
              7787900129957441143457185792)
assert new<prev
gain=prev-new
print("retained_run21_r11",prev,float(prev))
print("new_r11",new,float(new))
print("gain",gain,float(gain))

# For comparison, the analogous m=9,p=7 selected-plane LP cannot beat the
# retained run21 n=10 certificate; this is checked algebraically using the
# previously computed selected-plane caps.  We do not relabel n=10.
b9=Fraction(19,30); e9=Fraction(0)
for d in range(2,5):
    z1=qb(d,1,7); z2=qb(d,2,7)
    j33=min(z2,comb(36,2)); j34=min(z2,36*54)
    assert Fraction(z1)-b9*j33-e9*j34 >= 1
print("n10_selected-plane route does not improve retained run21 bound PASS")
print("SELF-CHECK PASS")
